// Typed view of public/pong/manifest.json, generated by scripts/pong-assets/build.mjs.

import raw from "../../public/pong/manifest.json";

export interface SpriteDef {
  file: string;
  /** 1x pixel size */
  w: number;
  h: number;
  /** 2x file pixel size (never upscaled beyond the source art) */
  w2: number;
  h2: number;
  kind?: string;
  anchor?: { x: number; y: number };
  orb?: { x: number; y: number; r: number };
}

export interface WeaponDef {
  sprite: string;
  strikeTop: number;
  strikeBottom: number;
  /** Right-most u of the hit zone: the face that meets the ball. */
  faceU: number;
  sweet: { v: number; half: number };
  /** Compound convex polygons in sprite-normalised (u, v) space. */
  polys: number[][][];
}

export interface AnimationDef {
  frames: string[];
  fps: number;
  roles?: Record<string, number | number[]>;
  wings?: { left: number; right: number; shoulderY: number };
}

export interface ArenaDef {
  file: string;
  w: number;
  h: number;
  has2x: boolean;
  /** x of the painted centre line in 1x output px (null: the plate has none). Court centre is w / 2. */
  centreLineX?: number | null;
}

export interface PongManifest {
  version: number;
  sprites: Record<string, SpriteDef>;
  animations: Record<string, AnimationDef>;
  weapons: Record<string, WeaponDef>;
  arenas: Record<string, ArenaDef>;
  notes: Record<string, unknown> & { title?: { file: string; w: number; h: number }; totalBytes?: number };
}

export const MANIFEST = raw as unknown as PongManifest;

/** Every image file the game can request, 1x and 2x, relative to /pong/. */
export function manifestFiles(m: PongManifest = MANIFEST): string[] {
  const files: string[] = [];
  for (const s of Object.values(m.sprites)) files.push(`${s.file}.webp`, `${s.file}@2x.webp`);
  for (const a of Object.values(m.arenas)) {
    files.push(`${a.file}.webp`);
    if (a.has2x) files.push(`${a.file}@2x.webp`);
  }
  if (m.notes.title) files.push(`${m.notes.title.file}.webp`);
  return files;
}
